// n8n Code node: "Normalize Meta lead" (mode: Run Once for Each Item)
// Turns a Meta Lead Ads lead into the SAME payload the Kids LP form sends,
// so the existing /webhook/alkimi-kids flow saves it to the sheet and fires the email alert.
const lead = $json;

// 1. Answers: works with the simplified output ({ data: {...} }) and the raw one ({ field_data: [...] })
const answers = {};
if (lead.data && typeof lead.data === 'object' && !Array.isArray(lead.data)) {
  Object.assign(answers, lead.data);
}
if (Array.isArray(lead.field_data)) {
  for (const f of lead.field_data) answers[f.name] = Array.isArray(f.values) ? f.values.join(', ') : f.values;
}

// Meta builds custom-question keys from the question text, so match by keyword instead of exact key
const pick = (...patterns) => {
  for (const [k, v] of Object.entries(answers)) {
    if (patterns.some(p => p.test(k))) return String(v ?? '');
  }
  return '';
};
const clean = v => String(v || '').replace(/_/g, ' ').replace(/\s+/g, ' ').trim();

const name = pick(/^full_?name$/i, /^name$/i) ||
  [pick(/^first_?name$/i), pick(/^last_?name$/i)].filter(Boolean).join(' ');
const email = pick(/^email$/i, /e-?mail/i);
const phone = pick(/^phone(_number)?$/i, /phone/i);

const childAge  = clean(pick(/how_?old/i, /child.?s?_?age/i, /^age$/i));                    // "How old is your child?"
const goal      = clean(pick(/matters/i, /goal/i));               // "What matters most to you right now?"
const location  = clean(pick(/south_?austin/i, /convenient/i));   // "Is South Austin convenient for you?"
const feeOk     = clean(pick(/fee/i));                      // "$20 trial class fee... does that work?"
const childName = clean(pick(/child.?s?_?name/i));                // only if you add this question later

// 2. Attribution: the ad name carries the creative (screen_time_v1, bullying_v2, energy_v1...)
const get = (...paths) => {
  for (const p of paths) {
    const v = p.split('.').reduce((o, k) => (o == null ? undefined : o[k]), lead);
    if (v) return String(v);
  }
  return '';
};
const adName     = get('ad_name', 'ad.name');
const adsetName  = get('adset_name', 'adset.name');
const campaign   = get('campaign_name', 'campaign.name');
const formName   = get('form_name', 'form.name');
const angleMatch = adName.toLowerCase().match(/(screen_time|bullying|energy)_v\d+/);
const isOrganic  = lead.is_organic === true || lead.is_organic === 'true';

const created = get('created_time');
const submittedAt = created ? new Date(created).toISOString() : new Date().toISOString();

return {
  json: {
    // same fields as the LP form
    submitted_at: submittedAt,
    lp: 'kids',                                   // keeps the Kids layout in the email alert
    name, email, phone,
    child_name: childName,
    child_age: childAge,
    utm_source: 'facebook',
    utm_medium: isOrganic ? 'organic_lead_form' : 'lead_form',   // LP traffic uses paid_social
    utm_campaign: campaign || 'alkimi_kids_leadgen_oct26',
    utm_term: adsetName,
    utm_content: angleMatch ? angleMatch[0] : adName,
    gclid: '', gbraid: '', wbraid: '', fbclid: '',
    landing_page: 'meta_lead_form' + (formName ? ': ' + formName : ''),
    referrer: '',
    // extra fields from the native form (map them in the sheet node to keep them)
    lead_source: 'meta_form',
    meta_lead_id: get('id', 'leadgen_id'),
    goal, location_fit: location, fee_ok: feeOk,
  },
};
